package zero.learning;

import com.sun.net.httpserver.HttpServer;
import java.net.InetSocketAddress;
import java.util.concurrent.Executors;

/** Explicit local-only entry; the public static site never contacts this service automatically. */
public final class App {
    private App() {}
    public static void main(String[] args) throws Exception {
        BookRepository repository = new BookRepository("jdbc:h2:mem:zero_learning;DB_CLOSE_DELAY=-1");
        repository.initialise();
        HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 18423), 0);
        server.createContext("/api/books/", new BookController(new BookService(repository)));
        var executor = Executors.newFixedThreadPool(2);
        server.setExecutor(executor);
        Runtime.getRuntime().addShutdownHook(new Thread(() -> { server.stop(0); executor.shutdownNow(); }));
        server.start();
        System.out.println("学習用API: http://127.0.0.1:18423/api/books/1 （メモリ内H2、停止時に消える）");
    }
}

package zero.learning;

/** A tiny value returned from the repository. */
public record Book(long id, String title) {}

package zero.learning;

import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpHandler;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.sql.SQLException;
import java.util.Optional;

/** Loopback-only learning example, not an internet-facing production server. */
public final class BookController implements HttpHandler {
    private final BookService service;
    public BookController(BookService service) { this.service = service; }

    @Override public void handle(HttpExchange ex) throws IOException {
        int status;
        String json;
        try {
            String prefix = "/api/books/";
            String path = ex.getRequestURI().getPath();
            if (!path.startsWith(prefix)) {
                status = 404; json = "{\"error\":\"not_found\"}";
            } else if ("GET".equals(ex.getRequestMethod())) {
                Optional<Book> found = service.find(path.substring(prefix.length()));
                status = found.isPresent() ? 200 : 404;
                json = found.map(BookController::bookJson).orElse("{\"error\":\"not_found\"}");
            } else if ("PUT".equals(ex.getRequestMethod()) || "POST".equals(ex.getRequestMethod())) {
                String contentType = ex.getRequestHeaders().getFirst("Content-Type");
                if (contentType == null || !contentType.split(";", 2)[0].trim().equalsIgnoreCase("text/plain")) {
                    status = 415; json = "{\"error\":\"text_plain_required\"}";
                } else {
                    byte[] bytes = ex.getRequestBody().readNBytes(4097);
                    if (bytes.length > 4096) {
                        status = 413; json = "{\"error\":\"body_too_large\"}";
                    } else {
                        String title = new String(bytes, StandardCharsets.UTF_8);
                        if ("POST".equals(ex.getRequestMethod())) {
                            Optional<Book> created = service.create(path.substring(prefix.length()), title);
                            status = created.isPresent() ? 201 : 409;
                            json = created.map(BookController::bookJson).orElse("{\"error\":\"already_exists\"}");
                        } else {
                            Optional<Book> changed = service.rename(path.substring(prefix.length()), title);
                            status = changed.isPresent() ? 200 : 404;
                            json = changed.map(BookController::bookJson).orElse("{\"error\":\"not_found\"}");
                        }
                    }
                }
            } else if ("DELETE".equals(ex.getRequestMethod())) {
                boolean deleted = service.delete(path.substring(prefix.length()));
                status = deleted ? 200 : 404;
                json = deleted ? "{\"deleted\":true}" : "{\"error\":\"not_found\"}";
            } else {
                status = 405; json = "{\"error\":\"method_not_allowed\"}";
            }
        } catch (IllegalArgumentException e) {
            status = 400; json = "{\"error\":\"invalid_input\"}";
        } catch (SQLException e) {
            // Do not return SQL or connection details to the client.
            status = 503; json = "{\"error\":\"storage_unavailable\"}";
        }
        byte[] body = json.getBytes(StandardCharsets.UTF_8);
        ex.getResponseHeaders().set("Content-Type", "application/json; charset=utf-8");
        ex.sendResponseHeaders(status, body.length);
        try (var stream = ex.getResponseBody()) { stream.write(body); }
    }

    static String bookJson(Book b) { return "{\"id\":" + b.id() + ",\"title\":" + quote(b.title()) + "}"; }
    static String quote(String value) {
        StringBuilder result = new StringBuilder("\"");
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            switch (c) {
                case '"' -> result.append("\\\"");
                case '\\' -> result.append("\\\\");
                case '\n' -> result.append("\\n");
                case '\r' -> result.append("\\r");
                case '\t' -> result.append("\\t");
                default -> { if (c < 0x20) result.append(String.format("\\u%04x", (int)c)); else result.append(c); }
            }
        }
        return result.append('"').toString();
    }
}

package zero.learning;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.Optional;

/** Each operation owns a JDBC connection. The demo URL is an isolated H2 in-memory DB. */
public final class BookRepository {
    private final String jdbcUrl;

    public BookRepository(String jdbcUrl) { this.jdbcUrl = jdbcUrl; }
    private Connection open() throws SQLException { return DriverManager.getConnection(jdbcUrl, "sa", ""); }

    public void initialise() throws SQLException {
        try (Connection c = open(); Statement st = c.createStatement()) {
            st.execute("CREATE TABLE IF NOT EXISTS books (id BIGINT PRIMARY KEY, title VARCHAR(80) NOT NULL)");
            // H2-specific seed syntax; the fixture is not an existing business DB.
            st.execute("MERGE INTO books KEY(id) VALUES (1, 'Java入門'), (2, 'Rust入門')");
        }
    }

    public Optional<Book> findById(long id) throws SQLException {
        String sql = "SELECT id, title FROM books WHERE id = ?";
        try (Connection c = open(); PreparedStatement ps = c.prepareStatement(sql)) {
            ps.setLong(1, id); // SQL and the input value are kept separate.
            try (ResultSet rs = ps.executeQuery()) {
                return rs.next() ? Optional.of(new Book(rs.getLong("id"), rs.getString("title"))) : Optional.empty();
            }
        }
    }

    /** Return false for a duplicate ID; all other database failures propagate. */
    public boolean insert(long id, String title) throws SQLException {
        try (Connection c = open(); PreparedStatement ps = c.prepareStatement("INSERT INTO books (id, title) VALUES (?, ?)")) {
            ps.setLong(1, id);
            ps.setString(2, title);
            return ps.executeUpdate() == 1;
        } catch (SQLException e) {
            // The bundled H2 fixture reports primary-key conflicts with SQLState 23505.
            if ("23505".equals(e.getSQLState())) return false;
            throw e;
        }
    }

    public boolean delete(long id) throws SQLException {
        try (Connection c = open(); PreparedStatement ps = c.prepareStatement("DELETE FROM books WHERE id = ?")) {
            ps.setLong(1, id);
            return ps.executeUpdate() == 1;
        }
    }

    public boolean updateTitle(long id, String title) throws SQLException {
        return updateTitleForTest(id, title, false);
    }

    // Failure injection is package-private and used only by the local test fixture.
    boolean updateTitleForTest(long id, String title, boolean failAfterUpdate) throws SQLException {
        try (Connection c = open()) {
            c.setAutoCommit(false);
            try (PreparedStatement ps = c.prepareStatement("UPDATE books SET title = ? WHERE id = ?")) {
                ps.setString(1, title);
                ps.setLong(2, id);
                int changed = ps.executeUpdate();
                if (failAfterUpdate) throw new SQLException("fixture failure after update");
                c.commit();
                return changed == 1;
            } catch (SQLException e) {
                try { c.rollback(); } catch (SQLException rollback) { e.addSuppressed(rollback); }
                throw e;
            }
        }
    }
}

package zero.learning;

import java.sql.SQLException;
import java.util.Optional;

/** Input and business rules live here; HTTP and SQL have separate responsibilities. */
public final class BookService {
    private final BookRepository repository;
    public BookService(BookRepository repository) { this.repository = repository; }

    public static long validId(String text) {
        if (text == null || !text.matches("[1-9][0-9]{0,8}")) {
            throw new IllegalArgumentException("id must be a positive decimal integer of at most 9 digits");
        }
        return Long.parseLong(text);
    }
    public Optional<Book> find(String idText) throws SQLException {
        return repository.findById(validId(idText));
    }
    private static String validTitle(String title) {
        if (title == null || title.isBlank() || title.length() > 80) {
            throw new IllegalArgumentException("title must contain 1 to 80 UTF-16 code units");
        }
        return title;
    }
    public Optional<Book> create(String idText, String title) throws SQLException {
        long id = validId(idText);
        String checkedTitle = validTitle(title);
        if (!repository.insert(id, checkedTitle)) return Optional.empty();
        return Optional.of(new Book(id, checkedTitle));
    }
    public Optional<Book> rename(String idText, String title) throws SQLException {
        long id = validId(idText);
        String checkedTitle = validTitle(title);
        if (!repository.updateTitle(id, checkedTitle)) return Optional.empty();
        return Optional.of(new Book(id, checkedTitle));
    }
    public boolean delete(String idText) throws SQLException {
        return repository.delete(validId(idText));
    }
}

package zero.learning.projects;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.OptionalDouble;

/** Local, deterministic study-record example. No database or external service. */
public final class ReviewSchedule {
    private static final int[] DAYS = {1, 3, 7, 14, 30};
    private ReviewSchedule() {}
    public record Attempt(boolean correct, boolean helped) {}
    public record Summary(int blindCorrect, int assistedCorrect, int incorrect) {}
    public record Due(String problemId, LocalDate date) {
        public Due {
            Objects.requireNonNull(problemId, "problemId");
            Objects.requireNonNull(date, "date");
            if (problemId.isBlank()) throw new IllegalArgumentException("problemId must not be blank");
        }
    }

    /** correct+helped is distinct from a correct answer without assistance. */
    public static Summary summarize(List<Attempt> attempts) {
        Objects.requireNonNull(attempts, "attempts");
        int blind = 0, assisted = 0, wrong = 0;
        for (Attempt attempt : attempts) {
            Objects.requireNonNull(attempt, "attempt");
            if (!attempt.correct()) wrong++;
            else if (attempt.helped()) assisted++;
            else blind++;
        }
        return new Summary(blind, assisted, wrong);
    }

    /** A wrong answer resets the interval; help does not increase independent recall. */
    public static int nextCount(int current, Attempt attempt) {
        if (current < 0) throw new IllegalArgumentException("current must be nonnegative");
        Objects.requireNonNull(attempt, "attempt");
        if (!attempt.correct()) return 0;
        if (attempt.helped()) return current;
        return current == Integer.MAX_VALUE ? current : current + 1;
    }

    /** Accuracy includes both kinds of correct answer; no data has no numeric rate. */
    public static OptionalDouble accuracy(Summary summary) {
        Objects.requireNonNull(summary, "summary");
        if (summary.blindCorrect() < 0 || summary.assistedCorrect() < 0 || summary.incorrect() < 0)
            throw new IllegalArgumentException("counts must be nonnegative");
        long correct = (long) summary.blindCorrect() + summary.assistedCorrect();
        long total = correct + summary.incorrect();
        return total == 0 ? OptionalDouble.empty() : OptionalDouble.of((double) correct / total);
    }

    /** Keeps caller order; a date equal to today is already due. */
    public static List<Due> dueOnOrBefore(List<Due> items, LocalDate today) {
        Objects.requireNonNull(items, "items");
        Objects.requireNonNull(today, "today");
        // TODO: 今日以前の項目だけを入力順に集める
        return List.copyOf(items);
    }

    /** Return a new immutable history; never mutate the caller's list. */
    public static List<Attempt> append(List<Attempt> history, Attempt attempt) {
        Objects.requireNonNull(history, "history");
        Objects.requireNonNull(attempt, "attempt");
        List<Attempt> next = new ArrayList<>(history);
        next.add(attempt);
        return List.copyOf(next);
    }

    public static Optional<Attempt> latest(List<Attempt> history) {
        Objects.requireNonNull(history, "history");
        return history.isEmpty() ? Optional.empty() : Optional.of(history.get(history.size() - 1));
    }

    /** This is a starting schedule, not a scientifically universal optimum. */
    public static LocalDate nextReview(LocalDate from, int successfulRecalls) {
        Objects.requireNonNull(from, "from");
        if (successfulRecalls < 0) throw new IllegalArgumentException("successfulRecalls must be nonnegative");
        return from.plusDays(DAYS[Math.min(successfulRecalls, DAYS.length - 1)]);
    }
}

package zero.learning.projects;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Objects;

/** Search over supplied strings only; there is no network or dynamic execution. */
public final class SearchIndex {
    private static final int LIMIT = 20;
    private SearchIndex() {}
    public record Lesson(String id, String title, String category) {
        public Lesson {
            Objects.requireNonNull(id, "id"); Objects.requireNonNull(title, "title"); Objects.requireNonNull(category, "category");
            if (id.isBlank()) throw new IllegalArgumentException("id must not be blank");
        }
    }
    public static List<String> find(List<String> titles, String query) {
        Objects.requireNonNull(titles, "titles"); Objects.requireNonNull(query, "query");
        String needle = query.trim().toLowerCase(Locale.ROOT);
        if (needle.isEmpty()) return List.of();
        List<String> matches = new ArrayList<>();
        for (String title : titles) {
            Objects.requireNonNull(title, "title");
            if (title.toLowerCase(Locale.ROOT).contains(needle)) {
                matches.add(title);
                if (matches.size() == LIMIT) break;
            }
        }
        return List.copyOf(matches);
    }

    /** Validate a query without modifying or saving it. The limit is Unicode code points. */
    public static boolean validQuery(String query) {
        Objects.requireNonNull(query, "query");
        String stripped = query.strip();
        return !stripped.isEmpty() && stripped.codePointCount(0, stripped.length()) <= 80;
    }

    /** AND matching, using Java whitespace and ROOT case conversion, with no NFKC. */
    public static boolean containsAllTerms(String title, String query) {
        Objects.requireNonNull(title, "title"); Objects.requireNonNull(query, "query");
        String stripped = query.strip();
        if (stripped.isEmpty()) return false;
        String text = title.toLowerCase(Locale.ROOT);
        for (String term : stripped.split("\\p{javaWhitespace}+")) {
            if (!text.contains(term.toLowerCase(Locale.ROOT))) return false;
        }
        return true;
    }

    /** Deduplicate exact IDs only, retaining first occurrence and unknown IDs. */
    public static List<String> uniqueIds(List<String> ids) {
        Objects.requireNonNull(ids, "ids");
        var seen = new LinkedHashSet<String>();
        for (String id : ids) seen.add(Objects.requireNonNull(id, "id"));
        return List.copyOf(seen);
    }

    /** A page is independent of the caller list; size is between 1 and 20 inclusive. */
    public static List<String> slicePage(List<String> items, int offset, int size) {
        Objects.requireNonNull(items, "items");
        if (offset < 0 || size < 1 || size > LIMIT) throw new IllegalArgumentException("invalid page");
        if (offset >= items.size()) return List.of();
        int end = (int) Math.min((long) offset + size, items.size());
        return List.copyOf(items.subList(offset, end));
    }

    /** Category IDs are compared exactly; no identifiers are normalized or deleted. */
    public static List<Lesson> filterCategory(List<Lesson> lessons, String category) {
        Objects.requireNonNull(lessons, "lessons"); Objects.requireNonNull(category, "category");
        List<Lesson> matches = new ArrayList<>();
        for (Lesson lesson : lessons) {
            Objects.requireNonNull(lesson, "lesson");
            if (lesson.category().equals(category)) matches.add(lesson);
        }
        return List.copyOf(matches);
    }

    /** Return an exact match's UTF-16 index; this does not change case or width. */
    public static int indexExact(String title, String needle) {
        Objects.requireNonNull(title, "title"); Objects.requireNonNull(needle, "needle");
        if (needle.isEmpty()) return -1;
        return title.indexOf(needle);
    }
}

package zero.learning;

import static org.junit.jupiter.api.Assertions.*;
import com.sun.net.httpserver.HttpServer;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.util.UUID;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class BookFlowTest {
    private String url;
    private BookRepository repository;
    private HttpServer server;
    private ExecutorService executor;
    private HttpClient client;
    private String origin;

    @BeforeEach void start() throws Exception {
        url = "jdbc:h2:mem:test_" + UUID.randomUUID().toString().replace("-", "") + ";DB_CLOSE_DELAY=-1";
        repository = new BookRepository(url); repository.initialise();
        server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
        server.createContext("/api/books/", new BookController(new BookService(repository)));
        executor = Executors.newFixedThreadPool(2); server.setExecutor(executor); server.start();
        client = HttpClient.newHttpClient(); origin = "http://127.0.0.1:" + server.getAddress().getPort();
    }
    @AfterEach void stop() { server.stop(0); executor.shutdownNow(); }
    private HttpResponse<String> get(String id) throws Exception {
        return client.send(HttpRequest.newBuilder(URI.create(origin + "/api/books/" + id)).GET().build(), HttpResponse.BodyHandlers.ofString());
    }
    private HttpResponse<String> put(String id, String title) throws Exception {
        return client.send(HttpRequest.newBuilder(URI.create(origin + "/api/books/" + id)).header("Content-Type", "text/plain; charset=utf-8").PUT(HttpRequest.BodyPublishers.ofString(title)).build(), HttpResponse.BodyHandlers.ofString());
    }
    private HttpResponse<String> post(String id, String title) throws Exception {
        return client.send(HttpRequest.newBuilder(URI.create(origin + "/api/books/" + id)).header("Content-Type", "text/plain; charset=utf-8").POST(HttpRequest.BodyPublishers.ofString(title)).build(), HttpResponse.BodyHandlers.ofString());
    }
    private HttpResponse<String> delete(String id) throws Exception {
        return client.send(HttpRequest.newBuilder(URI.create(origin + "/api/books/" + id)).DELETE().build(), HttpResponse.BodyHandlers.ofString());
    }

    @Test void normalRequestUsesHttpJdbcAndJson() throws Exception {
        var r = get("1"); assertEquals(200, r.statusCode()); assertEquals("{\"id\":1,\"title\":\"Java入門\"}", r.body());
        assertTrue(r.headers().firstValue("Content-Type").orElseThrow().startsWith("application/json"));
    }
    @Test void validateIds() {
        assertEquals(1L, BookService.validId("1"));
        assertEquals(999999999L, BookService.validId("999999999"));
        for (String bad : new String[]{"0", "abc", "", "1000000000", "-1"}) {
            assertThrows(IllegalArgumentException.class, () -> BookService.validId(bad));
        }
        assertThrows(IllegalArgumentException.class, () -> BookService.validId(null));
    }
    @Test void invalidInputAndMissingAreDifferent() throws Exception {
        assertEquals(400, get("abc").statusCode()); assertEquals(400, get("0").statusCode()); assertEquals(404, get("99").statusCode());
        assertEquals(400, put("1", " ").statusCode());
    }
    @Test void databaseFailureIs503WithoutLeakingSql() throws Exception {
        try (var c = DriverManager.getConnection(url, "sa", ""); var st = c.createStatement()) { st.execute("DROP TABLE books"); }
        var r = get("1"); assertEquals(503, r.statusCode()); assertEquals("{\"error\":\"storage_unavailable\"}", r.body());
    }
    @Test void updateCommitsAndForcedFailureRollsBack() throws Exception {
        var r = put("1", "Java 17"); assertEquals(200, r.statusCode()); assertEquals("Java 17", repository.findById(1).orElseThrow().title());
        assertThrows(SQLException.class, () -> repository.updateTitleForTest(1, "must roll back", true));
        assertEquals("Java 17", repository.findById(1).orElseThrow().title());
        assertEquals(404, put("99", "absent").statusCode());
    }
    @Test void twoRequestsAreIndependent() throws Exception {
        var a = HttpRequest.newBuilder(URI.create(origin + "/api/books/1")).GET().build();
        var b = HttpRequest.newBuilder(URI.create(origin + "/api/books/2")).GET().build();
        CompletableFuture<HttpResponse<String>> one = client.sendAsync(a, HttpResponse.BodyHandlers.ofString());
        CompletableFuture<HttpResponse<String>> two = client.sendAsync(b, HttpResponse.BodyHandlers.ofString());
        assertTrue(one.join().body().contains("Java入門")); assertTrue(two.join().body().contains("Rust入門"));
        assertEquals(200, one.join().statusCode()); assertEquals(200, two.join().statusCode());
    }
    @Test void requestBodyLimitsAndContentTypeAreExplicit() throws Exception {
        var wrongType = HttpRequest.newBuilder(URI.create(origin + "/api/books/1"))
                .header("Content-Type", "application/json").PUT(HttpRequest.BodyPublishers.ofString("{}")) .build();
        assertEquals(415, client.send(wrongType, HttpResponse.BodyHandlers.ofString()).statusCode());
        assertEquals(413, put("1", "a".repeat(4097)).statusCode());
        assertEquals(400, put("1", "a".repeat(81)).statusCode());
    }
    @Test void createReadUpdateDeleteAndDuplicateIdAreDistinct() throws Exception {
        assertEquals(404, get("3").statusCode());
        var created = post("3", "Java ' OR 1=1 --");
        assertEquals(201, created.statusCode());
        assertEquals("Java ' OR 1=1 --", repository.findById(3).orElseThrow().title());
        assertEquals(200, get("3").statusCode());
        assertEquals(409, post("3", "must not overwrite").statusCode());
        assertEquals("Java ' OR 1=1 --", repository.findById(3).orElseThrow().title());
        assertEquals(200, put("3", "updated").statusCode());
        assertEquals("updated", repository.findById(3).orElseThrow().title());
        var deleted = delete("3");
        assertEquals(200, deleted.statusCode()); assertEquals("{\"deleted\":true}", deleted.body());
        assertEquals(404, get("3").statusCode()); assertEquals(404, delete("3").statusCode());
        assertEquals(400, post("abc", "title").statusCode()); assertEquals(400, post("4", " ").statusCode());
        assertEquals(400, delete("0").statusCode()); assertEquals(413, post("4", "a".repeat(4097)).statusCode());
        assertTrue(repository.findById(1).isPresent());
    }
    @Test void createAndRenameValidateTitlesBeforeDatabase() throws Exception {
        var service = new BookService(repository);
        assertThrows(IllegalArgumentException.class, () -> service.create("4", null));
        assertThrows(IllegalArgumentException.class, () -> service.create("4", "a".repeat(81)));
        assertTrue(service.create("4", "a".repeat(80)).isPresent());
        assertThrows(IllegalArgumentException.class, () -> service.rename("4", "\t\n"));
        assertEquals("a".repeat(80), repository.findById(4).orElseThrow().title());
    }
    @Test void titleIsEscapedAsJsonAndIdIsValidatedBeforeSql() throws Exception {
        var r = put("1", "A\"B\\C\nD"); assertEquals(200, r.statusCode()); assertEquals("{\"id\":1,\"title\":\"A\\\"B\\\\C\\nD\"}", r.body());
        assertThrows(IllegalArgumentException.class, () -> new BookService(repository).find("1 OR 1=1"));
    }
}

package zero.learning.projects;
import static org.junit.jupiter.api.Assertions.*;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;
class ReviewScheduleTest {
    @Test void summarizeDistinguishesAssistanceAndErrors() {
        var attempts = List.of(new ReviewSchedule.Attempt(true, false), new ReviewSchedule.Attempt(true, true), new ReviewSchedule.Attempt(false, true));
        assertEquals(new ReviewSchedule.Summary(1,1,1), ReviewSchedule.summarize(attempts));
        assertEquals(new ReviewSchedule.Summary(0,0,0), ReviewSchedule.summarize(List.of()));
        assertThrows(NullPointerException.class, () -> ReviewSchedule.summarize(null));
    }
    @Test void recallCountRequiresIndependentSuccessAndResetsOnFailure() {
        var blind = new ReviewSchedule.Attempt(true, false);
        var helped = new ReviewSchedule.Attempt(true, true);
        var wrong = new ReviewSchedule.Attempt(false, false);
        assertEquals(3, ReviewSchedule.nextCount(2, blind));
        assertEquals(2, ReviewSchedule.nextCount(2, helped));
        assertEquals(0, ReviewSchedule.nextCount(2, wrong));
        assertEquals(Integer.MAX_VALUE, ReviewSchedule.nextCount(Integer.MAX_VALUE, blind));
        assertThrows(IllegalArgumentException.class, () -> ReviewSchedule.nextCount(-1, blind));
        assertThrows(NullPointerException.class, () -> ReviewSchedule.nextCount(1, null));
    }
    @Test void accuracyHasNoValueWithoutAttemptsAndAvoidsOverflow() {
        assertTrue(ReviewSchedule.accuracy(new ReviewSchedule.Summary(0,0,0)).isEmpty());
        assertEquals(2.0/3.0, ReviewSchedule.accuracy(new ReviewSchedule.Summary(1,1,1)).orElseThrow(), 1e-12);
        assertEquals(2.0/3.0, ReviewSchedule.accuracy(new ReviewSchedule.Summary(Integer.MAX_VALUE,Integer.MAX_VALUE,Integer.MAX_VALUE)).orElseThrow(), 1e-12);
        assertThrows(IllegalArgumentException.class, () -> ReviewSchedule.accuracy(new ReviewSchedule.Summary(-1,0,0)));
        assertThrows(NullPointerException.class, () -> ReviewSchedule.accuracy(null));
    }
    @Test void dueItemsIncludeTodayAndPreserveInputOrder() {
        LocalDate now = LocalDate.of(2026, 10, 28);
        var future = new ReviewSchedule.Due("future", now.plusDays(1));
        var past = new ReviewSchedule.Due("past", now.minusDays(1));
        var today = new ReviewSchedule.Due("today", now);
        var due = ReviewSchedule.dueOnOrBefore(List.of(future, past, today), now);
        assertEquals(List.of(past, today), due);
        assertThrows(UnsupportedOperationException.class, () -> due.add(future));
        assertThrows(NullPointerException.class, () -> ReviewSchedule.dueOnOrBefore(null, now));
        assertThrows(NullPointerException.class, () -> ReviewSchedule.dueOnOrBefore(List.of(), null));
        assertThrows(IllegalArgumentException.class, () -> new ReviewSchedule.Due(" ", now));
    }
    @Test void appendReturnsIndependentImmutableHistory() {
        var first = new ReviewSchedule.Attempt(true, true);
        var second = new ReviewSchedule.Attempt(false, false);
        var source = new ArrayList<>(List.of(first));
        var next = ReviewSchedule.append(source, second);
        assertEquals(List.of(first), source); assertEquals(List.of(first, second), next);
        source.clear(); assertEquals(2, next.size());
        assertThrows(UnsupportedOperationException.class, () -> next.add(first));
        assertThrows(NullPointerException.class, () -> ReviewSchedule.append(null, second));
        assertThrows(NullPointerException.class, () -> ReviewSchedule.append(List.of(), null));
    }
    @Test void latestHandlesEmptyAndReturnsLastAttempt() {
        var first = new ReviewSchedule.Attempt(true, false);
        var last = new ReviewSchedule.Attempt(false, false);
        assertTrue(ReviewSchedule.latest(List.of()).isEmpty());
        assertEquals(last, ReviewSchedule.latest(List.of(first, last)).orElseThrow());
        assertThrows(NullPointerException.class, () -> ReviewSchedule.latest(null));
    }
    @Test void reviewIntervalsCoverEdgesAndCap() {
        LocalDate from=LocalDate.of(2026,10,28);
        assertEquals(from.plusDays(1), ReviewSchedule.nextReview(from,0));
        assertEquals(from.plusDays(3), ReviewSchedule.nextReview(from,1));
        assertEquals(from.plusDays(7), ReviewSchedule.nextReview(from,2));
        assertEquals(from.plusDays(14), ReviewSchedule.nextReview(from,3));
        assertEquals(from.plusDays(30), ReviewSchedule.nextReview(from,4));
        assertEquals(from.plusDays(30), ReviewSchedule.nextReview(from,999));
        assertThrows(IllegalArgumentException.class, () -> ReviewSchedule.nextReview(from,-1));
        assertThrows(NullPointerException.class, () -> ReviewSchedule.nextReview(null,0));
    }
}

package zero.learning.projects;
import static org.junit.jupiter.api.Assertions.*;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;
class SearchIndexTest {
    @Test void caseInsensitiveSubstringKeepsOriginalTitlesAndOrder() {
        assertEquals(List.of("Java入門", "java応用"), SearchIndex.find(List.of("Java入門","Rust","java応用")," JAVA "));
        assertEquals(List.of("Java入門"), SearchIndex.find(List.of("Java入門","Rust"),"入門"));
        assertEquals(List.of(), SearchIndex.find(List.of("Java"),"Ｊａｖａ")); // No implicit NFKC.
    }
    @Test void queryValidationCountsUnicodeCodePointsWithoutChangingInput() {
        assertFalse(SearchIndex.validQuery("　 "));
        assertTrue(SearchIndex.validQuery("  Java  "));
        assertTrue(SearchIndex.validQuery("😀".repeat(80)));
        assertFalse(SearchIndex.validQuery("😀".repeat(81)));
        assertThrows(NullPointerException.class, () -> SearchIndex.validQuery(null));
    }
    @Test void allTermsMustMatchWithoutWidthNormalization() {
        assertTrue(SearchIndex.containsAllTerms("Java String 入門", " 入門　JAVA "));
        assertTrue(SearchIndex.containsAllTerms("Java String 入門", "string JAVA"));
        assertFalse(SearchIndex.containsAllTerms("Java String 入門", "JAVA Rust"));
        assertFalse(SearchIndex.containsAllTerms("Java", "Ｊａｖａ"));
        assertFalse(SearchIndex.containsAllTerms("Java", "　"));
        assertThrows(NullPointerException.class, () -> SearchIndex.containsAllTerms(null, "x"));
    }
    @Test void uniqueIdsKeepFirstOrderAndUnknownValues() {
        var source = List.of("java:q0001", "old-unknown", "java:q0001", "JAVA:Q0001", "rust:q0001");
        var result = SearchIndex.uniqueIds(source);
        assertEquals(List.of("java:q0001", "old-unknown", "JAVA:Q0001", "rust:q0001"), result);
        assertThrows(UnsupportedOperationException.class, () -> result.add("x"));
        var bad = new ArrayList<String>(); bad.add(null);
        assertThrows(NullPointerException.class, () -> SearchIndex.uniqueIds(bad));
        assertThrows(NullPointerException.class, () -> SearchIndex.uniqueIds(null));
    }
    @Test void pageBoundsAreCheckedAndResultIsIndependent() {
        var items = new ArrayList<>(List.of("a", "b", "c", "d"));
        var page = SearchIndex.slicePage(items, 1, 2);
        assertEquals(List.of("b", "c"), page);
        items.set(1, "changed"); assertEquals(List.of("b", "c"), page);
        assertThrows(UnsupportedOperationException.class, () -> page.add("x"));
        assertEquals(List.of(), SearchIndex.slicePage(items, Integer.MAX_VALUE, 20));
        assertThrows(IllegalArgumentException.class, () -> SearchIndex.slicePage(items, -1, 1));
        assertThrows(IllegalArgumentException.class, () -> SearchIndex.slicePage(items, 0, 0));
        assertThrows(IllegalArgumentException.class, () -> SearchIndex.slicePage(items, 0, 21));
    }
    @Test void categoryIdsAreExactAndOrderingIsPreserved() {
        var a = new SearchIndex.Lesson("java:q0001", "A", "core");
        var b = new SearchIndex.Lesson("rust:q0001", "B", "other");
        var c = new SearchIndex.Lesson("old-id", "C", "core");
        var result = SearchIndex.filterCategory(List.of(a,b,c), "core");
        assertEquals(List.of(a,c), result); assertEquals(List.of(), SearchIndex.filterCategory(List.of(a), "CORE"));
        assertThrows(UnsupportedOperationException.class, () -> result.add(b));
        assertThrows(NullPointerException.class, () -> SearchIndex.filterCategory(null, "core"));
        assertThrows(NullPointerException.class, () -> SearchIndex.filterCategory(List.of(a), null));
    }
    @Test void exactIndexUsesUtf16AndDoesNotNormalize() {
        assertEquals(3, SearchIndex.indexExact("A😀B", "B"));
        assertEquals(0, SearchIndex.indexExact("Java", "Ja"));
        assertEquals(-1, SearchIndex.indexExact("Java", "java"));
        assertEquals(-1, SearchIndex.indexExact("Java", "Ｊａｖａ"));
        assertEquals(-1, SearchIndex.indexExact("Java", ""));
        assertThrows(NullPointerException.class, () -> SearchIndex.indexExact(null, "x"));
    }
    @Test void blankQueryReturnsNothingAndResultsAreCapped() {
        assertEquals(List.of(), SearchIndex.find(List.of("Java")," "));
        var titles=new ArrayList<String>(); for(int i=0;i<25;i++) titles.add("Java"+i);
        var result=SearchIndex.find(titles,"java"); assertEquals(20,result.size()); assertEquals("Java19",result.get(19));
        assertThrows(UnsupportedOperationException.class, () -> result.add("mutation"));
        assertThrows(NullPointerException.class, () -> SearchIndex.find(null,"x"));
        assertThrows(NullPointerException.class, () -> SearchIndex.find(List.of("x"),null));
    }
}
